func(a *App)ws(repo *Repository)gin.HandlerFunc{return func(c *gin.Context){var p Poll;if e:=repo.db.Collection("polls").FindOne(c,bson.M{"_id":c.Param("id")}).Decode(&p);e!=nil{fail(c,404,"NOT_FOUND","Poll not found");return};origin:=c.GetHeader("Origin");allowed:=false;for _,o:=range origins(a.cfg.AllowedOrigins){if origin==o{allowed=true}};if origin!=""&&!allowed{fail(c,403,"FORBIDDEN","Origin is not allowed");return};up:=websocket.Upgrader{ReadBufferSize:1024,WriteBufferSize:4096,CheckOrigin:func(*http.Request)bool{return origin==""||allowed}};conn,e:=up.Upgrade(c.Writer,c.Request,nil);if e!=nil{return};defer conn.Close();_ = conn.SetReadDeadline(time.Now().Add(60*time.Second));conn.SetPongHandler(func(string)error{_ = conn.SetReadDeadline(time.Now().Add(60*time.Second));return nil});counts,e:=repo.counts(c,&p);if e!=nil{return};if e=conn.WriteJSON(makeResults(&p,counts));e!=nil{return};ctx,cancel:=context.WithCancel(context.Background());defer cancel();sub:=repo.redis.Subscribe(ctx,updateChannel(p.ID));defer sub.Close();go func(){for{if e:=conn.WriteControl(websocket.PingMessage,[]byte{},time.Now().Add(5*time.Second));e!=nil{cancel();return};time.Sleep(25*time.Second)}}();go func(){for{if _,_,e:=conn.ReadMessage();e!=nil{cancel();return}}}();for{select{case msg,open:=<-sub.Channel():if !open{return};_ = conn.SetWriteDeadline(time.Now().Add(10*time.Second));if e:=conn.WriteMessage(websocket.TextMessage,[]byte(msg.Payload));e!=nil{return};case<-ctx.Done():return}}}}
